from collections import OrderedDict


class Policy:
    def __init__(self, capacity_bytes):
        self.capacity = max(0, int(capacity_bytes))
        self.probation = OrderedDict()
        self.protected = OrderedDict()
        self.ghost_recent = OrderedDict()
        self.ghost_frequent = OrderedDict()
        self.probation_bytes = 0
        self.protected_bytes = 0
        self.used = 0
        self.target = self.capacity // 2
        self.ghost_bytes = 0
        self.ghost_limit = max(64, min(1 << 20, 2 * max(1, self.capacity)))
        self.ghost_count_limit = 4096
        self.serial = 0

    def _drop_ghost(self, key):
        for ghosts in (self.ghost_recent, self.ghost_frequent):
            value = ghosts.pop(key, None)
            if value is not None:
                self.ghost_bytes -= value[0]

    def _remember_ghost(self, key, size, kind):
        self._drop_ghost(key)
        self.serial += 1
        value = (max(1, int(size)), self.serial)
        if kind == 1:
            self.ghost_recent[key] = value
        else:
            self.ghost_frequent[key] = value
        self.ghost_bytes += value[0]
        self._trim_ghosts()

    def _trim_ghosts(self):
        while (self.ghost_bytes > self.ghost_limit or
               len(self.ghost_recent) + len(self.ghost_frequent) > self.ghost_count_limit):
            source = None
            oldest = None
            for ghosts in (self.ghost_recent, self.ghost_frequent):
                if ghosts:
                    value = next(iter(ghosts.values()))
                    if oldest is None or value[1] < oldest[1]:
                        oldest = value
                        source = ghosts
            _, value = source.popitem(last=False)
            self.ghost_bytes -= value[0]

    def _adjust_target(self, kind):
        if self.capacity <= 0:
            return
        recent = sum(value[0] for value in self.ghost_recent.values())
        frequent = sum(value[0] for value in self.ghost_frequent.values())
        if kind == 1:
            delta = self.capacity if recent == 0 else max(1, min(self.capacity, frequent // recent or 1))
            self.target = max(0, self.target - delta)
        else:
            delta = self.capacity if frequent == 0 else max(1, min(self.capacity, recent // frequent or 1))
            self.target = min(self.capacity, self.target + delta)

    def _demote_protected(self):
        if not self.protected:
            return False
        key, size = self.protected.popitem(last=False)
        self.protected_bytes -= size
        self.probation[key] = (size, 2)
        self.probation_bytes += size
        return True

    def _evict_probation(self):
        if not self.probation:
            return None
        key, value = self.probation.popitem(last=False)
        size, origin = value
        self.probation_bytes -= size
        self.used -= size
        self._remember_ghost(key, size, origin)
        return key

    def _make_room(self, incoming, protected_admission):
        evicted = []
        if protected_admission:
            limit = max(self.target, incoming)
            while self.protected and self.protected_bytes + incoming > limit:
                self._demote_protected()
        while self.used + incoming > self.capacity:
            key = self._evict_probation()
            if key is not None:
                evicted.append(key)
            elif not self._demote_protected():
                break
        return evicted

    def _unique(self, keys):
        result = []
        seen = set()
        for key in keys:
            if key not in seen:
                seen.add(key)
                result.append(key)
        return result

    def access(self, key, size, now):
        key = int(key)
        size = max(0, int(size))
        existing = 1 if key in self.probation else 2 if key in self.protected else 0

        if existing:
            if existing == 1:
                old_size, _ = self.probation.pop(key)
                self.probation_bytes -= old_size
            else:
                old_size = self.protected.pop(key)
                self.protected_bytes -= old_size
            self.used -= old_size
            if size <= 0 or size > self.capacity:
                return [key]
            evicted = self._make_room(size, True)
            if self.used + size > self.capacity:
                return self._unique(evicted + [key])
            self._drop_ghost(key)
            self.protected[key] = size
            self.protected_bytes += size
            self.used += size
            return self._unique(evicted)

        ghost_kind = 1 if key in self.ghost_recent else 2 if key in self.ghost_frequent else 0
        if size <= 0 or size > self.capacity:
            return []
        if ghost_kind:
            self._adjust_target(ghost_kind)
            self._drop_ghost(key)

        evicted = self._make_room(size, ghost_kind == 2)
        if self.used + size > self.capacity:
            return self._unique(evicted)
        if ghost_kind == 2:
            self.protected[key] = size
            self.protected_bytes += size
        else:
            self.probation[key] = (size, 1)
            self.probation_bytes += size
        self.used += size
        return self._unique(evicted)
